import { HttpClient, HttpErrorResponse, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

import { CarDto, CurrentUserDto, ManufacturerDto, ManufacturerRatingDto, RatingDto } from './dtos';

// Paths from ApiPaths.java, parameters from ApiParameters.java.
const ROOT = '/api';
const CARS = ROOT + '/cars';
const MANUFACTURERS = ROOT + '/manufacturers';
const RATING = '/ratings';
const RATINGS = ROOT + RATING;
const SESSION = ROOT + '/session';

/** ApiParameters.LOGIN_COOKIE */
export const LOGIN_COOKIE = 'LoggedInCookie';

/** CarsResource.LIMIT_ALL */
export const LIMIT_ALL = -1;

/** ManufacturersResource */
@Injectable({ providedIn: 'root' })
export class ManufacturersApi {
  private readonly http = inject(HttpClient);

  getManufacturers(): Observable<ManufacturerDto[]> {
    return this.http.get<ManufacturerDto[]>(MANUFACTURERS);
  }

  saveOrCreate(manufacturer: ManufacturerDto): Observable<ManufacturerDto> {
    return this.http.post<ManufacturerDto>(MANUFACTURERS, manufacturer);
  }

  delete(id: number): Observable<void> {
    return this.http.delete<void>(MANUFACTURERS + '/' + id);
  }

  getAverageRatings(): Observable<ManufacturerRatingDto[]> {
    return this.http.get<ManufacturerRatingDto[]>(MANUFACTURERS + RATING);
  }
}

/** RatingResource */
@Injectable({ providedIn: 'root' })
export class RatingsApi {
  private readonly http = inject(HttpClient);

  getRatings(): Observable<RatingDto[]> {
    return this.http.get<RatingDto[]>(RATINGS);
  }

  saveOrCreate(rating: RatingDto): Observable<RatingDto> {
    return this.http.post<RatingDto>(RATINGS, rating);
  }

  delete(id: number): Observable<void> {
    return this.http.delete<void>(RATINGS + '/' + id);
  }
}

/** CarsResource */
@Injectable({ providedIn: 'root' })
export class CarsApi {
  private readonly http = inject(HttpClient);

  getCars(offset = 0, limit = LIMIT_ALL): Observable<CarDto[]> {
    const params = new HttpParams().set('offset', offset).set('limit', limit);
    return this.http.get<CarDto[]>(CARS, { params });
  }
}

/** SessionResource */
@Injectable({ providedIn: 'root' })
export class SessionApi {
  private readonly http = inject(HttpClient);

  getCurrentUser(): Observable<CurrentUserDto> {
    return this.http.get<CurrentUserDto>(SESSION);
  }

  logout(): Observable<void> {
    return this.http.delete<void>(SESSION);
  }
}

/** Text for an error message, like ErrorHandlerAsyncCallback (HTTP status + status text). */
export function errorText(error: unknown): string {
  if (error instanceof HttpErrorResponse) {
    if (error.status === 0) {
      return 'Unable to reach the server.';
    }
    return 'HTTP ' + error.status + ': ' + (error.statusText || 'Error');
  }
  return error instanceof Error ? error.message : String(error);
}
