// Jackson serialises the Java bean properties, so the field names match the getters.

export interface ManufacturerDto {
  id: number | null;
  name: string;
  cars: CarDto[] | null;
}

export interface CarPropertiesDto {
  id: number | null;
  someString: string;
  someNumber: number | null;
  someDate: string | null;
  car: CarDto | null;
}

export interface CarDto {
  id: number | null;
  manufacturer: ManufacturerDto | null;
  model: string;
  ratings: RatingDto[] | null;
  carProperties: CarPropertiesDto | null;
}

export interface RatingDto {
  id: number | null;
  rating: number | null;
  car: CarDto | null;
}

export interface ManufacturerRatingDto {
  manufacturer: string;
  rating: number | null;
}

/**
 * Same as RatingDto.toString(): "Manufacturer/Model". The format is kept even when the car's
 * manufacturer has been deleted (the API then returns `manufacturer: null`): "/Model".
 */
export function ratingCarLabel(rating: RatingDto): string {
  const car = rating.car;
  if (!car) {
    return '';
  }
  return (car.manufacturer ? car.manufacturer.name : '') + '/' + car.model;
}

/** Same as CarRenderer: "Manufacturer Model". */
export function carLabel(car: CarDto | null): string {
  if (!car) {
    return '';
  }
  const manufacturer = car.manufacturer ? car.manufacturer.name : '';
  return manufacturer + ' ' + car.model;
}

export interface UserDto {
  id: number | null;
  username: string;
  firstName: string;
  lastName: string;
}

