import { ChangeDetectionStrategy, Component, OnInit, inject, input, output, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { ManufacturersApi, errorText } from '../api/api.service';
import { ManufacturerDto } from '../api/dtos';
import { MessageService } from '../messages/message.service';

/**
 * EditManufacturerPresenter/View: popup to create (manufacturer = null) or edit a manufacturer.
 * Save posts it and emits the saved manufacturer; Close (or a click on the glass) just closes.
 */
@Component({
  selector: 'app-edit-manufacturer',
  standalone: true,
  imports: [FormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="popupGlass" (click)="onGlassClick($event)">
      <div class="popupPanel" role="dialog" aria-label="Manufacturer">
        <div id="gwt-debug-manufacturer-editor">
          <div>
            <label for="gwt-debug-manufacturer-input">Name:</label>
            <input
              type="text"
              id="gwt-debug-manufacturer-input"
              name="name"
              [ngModel]="name()"
              (ngModelChange)="name.set($event)"
            />
          </div>

          <div>
            <button type="button" id="gwt-debug-manufacturer-save" [disabled]="saving()" (click)="onSave()">
              Save
            </button>
            <button type="button" id="gwt-debug-manufacturer-close" (click)="onCancel()">Close</button>
          </div>
        </div>
      </div>
    </div>
  `,
})
export class EditManufacturerComponent implements OnInit {
  private readonly api = inject(ManufacturersApi);
  private readonly messages = inject(MessageService);

  /** The manufacturer to edit, or null to create a new one. */
  readonly manufacturer = input<ManufacturerDto | null>(null);
  readonly saved = output<ManufacturerDto>();
  readonly closed = output<void>();

  protected readonly name = signal('');
  protected readonly saving = signal(false);

  ngOnInit(): void {
    this.name.set(this.manufacturer()?.name ?? '');
  }

  protected onSave(): void {
    const original = this.manufacturer();
    const manufacturer: ManufacturerDto = original
      ? { ...original, name: this.name() }
      : { id: null, name: this.name(), cars: [] };

    // The outcome of this save replaces any earlier message.
    this.messages.clear();
    this.saving.set(true);
    this.api.saveOrCreate(manufacturer).subscribe({
      next: (savedManufacturer) => {
        this.messages.success('The manufacturer has been saved.');
        this.saved.emit(savedManufacturer);
      },
      error: (error: unknown) => {
        this.saving.set(false);
        this.messages.error(errorText(error));
      },
    });
  }

  protected onCancel(): void {
    this.closed.emit();
  }

  /** autoHideEnabled: a click outside the popup closes it. */
  protected onGlassClick(event: MouseEvent): void {
    if (event.target === event.currentTarget) {
      this.onCancel();
    }
  }
}
