import { DecimalPipe } from '@angular/common';
import { ChangeDetectionStrategy, Component, OnInit, inject, signal } from '@angular/core';

import { ManufacturersApi, errorText } from '../api/api.service';
import { ManufacturerDto } from '../api/dtos';
import { MessageService } from '../messages/message.service';
import { onNavigationStart } from '../shell/on-navigation';
import { EditManufacturerComponent } from './edit-manufacturer.component';

/** Editor state: closed, creating a new manufacturer, or editing an existing one. */
type Editor = { open: false } | { open: true; manufacturer: ManufacturerDto | null };

/** ManufacturerPresenter/View: the manufacturer table with Edit and Delete per row. */
@Component({
  selector: 'app-manufacturer',
  standalone: true,
  imports: [DecimalPipe, EditManufacturerComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="bigTitle">
      <h2><span>Manufacturers</span></h2>
      <div class="actions">
        <button type="button" class="addAction" id="gwt-debug-create-manufacturer" (click)="onCreate()">
          Add manufacturer
        </button>
      </div>
      <span class="clear"></span>
    </div>

    <div class="tableWrapper">
      @if (loaded()) {
        <table class="cellTable" id="gwt-debug-manufacturers">
          <thead>
            <tr>
              <th class="w50">ID</th>
              <th>Name</th>
              <th class="w75">Edit</th>
              <th class="w75">Delete</th>
            </tr>
          </thead>
          <tbody>
            @for (manufacturer of manufacturers(); track manufacturer.id) {
              <tr>
                <td>{{ manufacturer.id | number }}</td>
                <td>{{ manufacturer.name }}</td>
                <td><button type="button" (click)="onEdit(manufacturer)">Edit</button></td>
                <td><button type="button" (click)="onDeleteClicked(manufacturer)">Delete</button></td>
              </tr>
            }
          </tbody>
        </table>
      } @else {
        <p>Loading...</p>
      }
    </div>

    @if (editor(); as editor) {
      @if (editor.open) {
        <app-edit-manufacturer
          [manufacturer]="editor.manufacturer"
          (saved)="onManufacturerSaved(editor.manufacturer, $event)"
          (closed)="closeEditor()"
        />
      }
    }
  `,
})
export class ManufacturerComponent implements OnInit {
  private readonly api = inject(ManufacturersApi);
  private readonly messages = inject(MessageService);

  protected readonly manufacturers = signal<ManufacturerDto[]>([]);
  protected readonly loaded = signal(false);
  protected readonly editor = signal<Editor>({ open: false });

  constructor() {
    onNavigationStart(() => this.closeEditor());
  }

  ngOnInit(): void {
    this.api.getManufacturers().subscribe({
      next: (manufacturers) => {
        this.manufacturers.set(manufacturers);
        this.loaded.set(true);
      },
      error: (error: unknown) => {
        this.loaded.set(true);
        this.messages.error(errorText(error));
      },
    });
  }

  protected onCreate(): void {
    this.editor.set({ open: true, manufacturer: null });
  }

  protected onEdit(manufacturer: ManufacturerDto): void {
    this.editor.set({ open: true, manufacturer });
  }

  protected closeEditor(): void {
    this.editor.set({ open: false });
  }

  /** ManufacturerAddedEvent: replace the edited row, or append a new one. */
  protected onManufacturerSaved(edited: ManufacturerDto | null, saved: ManufacturerDto): void {
    this.manufacturers.update((list) => {
      const index = edited ? list.findIndex((m) => m.id === edited.id) : -1;
      if (index < 0) {
        return [...list, saved];
      }
      const copy = [...list];
      copy[index] = saved;
      return copy;
    });
    this.closeEditor();
  }

  protected onDeleteClicked(manufacturer: ManufacturerDto): void {
    if (window.confirm('Are you sure you want to delete ' + manufacturer.name + '?')) {
      this.delete(manufacturer);
    }
  }

  private delete(manufacturer: ManufacturerDto): void {
    if (manufacturer.id === null) {
      return;
    }
    this.api.delete(manufacturer.id).subscribe({
      next: () => this.manufacturers.update((list) => list.filter((m) => m.id !== manufacturer.id)),
      error: (error: unknown) => this.messages.error(errorText(error)),
    });
  }
}
