import { ChangeDetectionStrategy, Component, OnDestroy, OnInit, input, output, signal } from '@angular/core';

import { Message } from './message.service';

const FADE_MS = 400;

/**
 * One message box (MessageWidget.ui.xml): the text in the first span, the "X" close link in
 * the last span. It fades in, closes itself after the message's delay, and is removed from
 * the DOM once faded out.
 */
@Component({
  selector: 'app-message-widget',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div
      class="message"
      [class.success]="message().style === 'success'"
      [class.error]="message().style === 'error'"
      [class.visible]="visible()"
      [id]="message().style === 'success' ? 'gwt-debug-successMessage' : 'gwt-debug-errorMessage'"
      role="status"
    >
      <span class="text">{{ message().text }}</span>
      <span class="close" title="Close" (click)="close()">X</span>
    </div>
  `,
  styles: `
    .message {
      position: relative;
      padding: 10px 30px 10px 10px;
      margin: 10px 0;
      border-radius: 5px;
      border: solid 1px;
      opacity: 0;
      transition: opacity 400ms linear;
    }
    .message.visible {
      opacity: 1;
    }
    .close {
      position: absolute;
      font-weight: bold;
      top: 5px;
      right: 10px;
      padding: 5px;
      cursor: pointer;
    }
    .success {
      color: #293a25;
      background-color: #cee4c8;
      border-color: #a2b89e;
    }
    .error {
      color: #ff0010;
      background-color: #e4cfc8;
      border-color: #b8a6a3;
    }
  `,
})
export class MessageWidgetComponent implements OnInit, OnDestroy {
  readonly message = input.required<Message>();
  readonly closed = output<Message>();

  protected readonly visible = signal(false);

  private closing = false;
  private readonly timers: ReturnType<typeof setTimeout>[] = [];

  ngOnInit(): void {
    // fadeIn
    this.timers.push(setTimeout(() => this.visible.set(true)));

    const delay = this.message().closeDelay;
    if (delay > 0) {
      this.timers.push(setTimeout(() => this.close(), delay));
    }
  }

  ngOnDestroy(): void {
    this.timers.forEach((timer) => clearTimeout(timer));
  }

  close(): void {
    if (this.closing) {
      return;
    }
    this.closing = true;
    // fadeOut, then remove from the DOM
    this.visible.set(false);
    this.timers.push(setTimeout(() => this.closed.emit(this.message()), FADE_MS));
  }
}
