import { Injectable, signal } from '@angular/core';

/** MessageStyle */
export type MessageStyle = 'success' | 'error';

/** MessageCloseDelay: NEVER = 0, DEFAULT = 5000 ms. */
export const CLOSE_DELAY_NEVER = 0;
export const CLOSE_DELAY_DEFAULT = 5000;

export interface Message {
  readonly id: number;
  readonly text: string;
  readonly style: MessageStyle;
  readonly closeDelay: number;
}

/** Replaces DisplayMessageEvent + MessagesPresenter: any screen can display a message. */
@Injectable({ providedIn: 'root' })
export class MessageService {
  private nextId = 1;
  private readonly list = signal<readonly Message[]>([]);

  readonly messages = this.list.asReadonly();

  success(text: string, closeDelay = CLOSE_DELAY_DEFAULT): void {
    this.display(text, 'success', closeDelay);
  }

  error(text: string, closeDelay = CLOSE_DELAY_DEFAULT): void {
    this.display(text, 'error', closeDelay);
  }

  display(text: string, style: MessageStyle, closeDelay = CLOSE_DELAY_DEFAULT): void {
    const message: Message = { id: this.nextId++, text, style, closeDelay };
    this.list.update((messages) => [...messages, message]);
  }

  /** Removes all messages at once, e.g. when a new save makes the previous outcome stale. */
  clear(): void {
    this.list.set([]);
  }

  remove(message: Message): void {
    this.list.update((messages) => messages.filter((m) => m.id !== message.id));
  }
}
