                }
              </select>
            </div>

            <div>
              <label for="gwt-debug-ratingInput">Your rating:</label>
              <input
                type="text"
                id="gwt-debug-ratingInput"
                name="rating"
                maxlength="3"
                [ngModel]="rating()"
                (ngModelChange)="rating.set($event)"
              />
