            </div>
          </div>
        </div>
      </div>
    }
  `,
})
export class EditRatingComponent implements OnInit {
  private readonly carsApi = inject(CarsApi);
  private readonly ratingsApi = inject(RatingsApi);
  private readonly messages = inject(MessageService);

  readonly saved = output<RatingDto>();
  readonly closed = output<void>();

  protected readonly carLabel = carLabel;
  protected readonly cars = signal<CarDto[] | null>(null);
  protected readonly car = signal<CarDto | null>(null);
  protected readonly rating = signal('');
  protected readonly saving = signal(false);

  ngOnInit(): void {
    this.carsApi.getCars(0, LIMIT_ALL).subscribe({
      next: (cars) => {
        this.car.set(cars.length > 0 ? cars[0] : null);
        this.cars.set(cars);
      },
      error: (error: unknown) => {
        this.messages.error(errorText(error));
        this.closed.emit();
      },
    });
  }

  protected onSave(): void {
    const rating: RatingDto = { id: null, car: this.car(), rating: parseInteger(this.rating()) };

    // The outcome of this save replaces any earlier message.
    this.messages.clear();
    this.saving.set(true);
    this.ratingsApi.saveOrCreate(rating).subscribe({
      next: (savedRating) => {
        this.messages.success('The rating has been saved.');
        this.saved.emit(savedRating);
      },
      error: (error: unknown) => {
        this.saving.set(false);
        this.messages.error(errorText(error));
      },
    });
  }

  protected onCancel(): void {
    this.closed.emit();
  }

  /** autoHideEnabled: a click outside the popup closes it. */
  protected onGlassClick(event: MouseEvent): void {
    if (event.target === event.currentTarget) {
      this.onCancel();
    }
  }
}

/** Like GWT's IntegerBox: an integer, or null when the text is empty or not a number. */
function parseInteger(text: string): number | null {
  const trimmed = text.trim().replace(/,/g, '');
  return /^[+-]?\d+$/.test(trimmed) ? parseInt(trimmed, 10) : null;
}
