                <td>{{ rating.rating | number }}</td>
                <td><button type="button" (click)="onDeleteClicked(rating)">Delete</button></td>
              </tr>
            }
          </tbody>
        </table>
      } @else {
        <p>Loading...</p>
      }
    </div>

    @if (creating()) {
      <app-edit-rating (saved)="onRatingAdded($event)" (closed)="creating.set(false)" />
    }
  `,
})
export class RatingComponent implements OnInit {
  private readonly api = inject(RatingsApi);
  private readonly messages = inject(MessageService);

  protected readonly carLabel = ratingCarLabel;
  protected readonly ratings = signal<RatingDto[]>([]);
  protected readonly loaded = signal(false);
  protected readonly creating = signal(false);

  constructor() {
    onNavigationStart(() => this.creating.set(false));
  }

  ngOnInit(): void {
    this.api.getRatings().subscribe({
      next: (ratings) => {
        this.ratings.set(ratings);
        this.loaded.set(true);
      },
      error: (error: unknown) => {
        this.loaded.set(true);
        this.messages.error(errorText(error));
      },
    });
  }

  protected onCreate(): void {
    this.creating.set(true);
  }

  /** RatingAddedEvent */
  protected onRatingAdded(rating: RatingDto): void {
    this.ratings.update((list) => [...list, rating]);
    this.creating.set(false);
  }

  protected onDeleteClicked(rating: RatingDto): void {
    if (window.confirm('Are you sure you want to delete ' + ratingCarLabel(rating) + '?')) {
      this.delete(rating);
    }
  }

  private delete(rating: RatingDto): void {
    if (rating.id === null) {
      return;
    }
    this.api.delete(rating.id).subscribe({
      next: () => this.ratings.update((list) => list.filter((r) => r.id !== rating.id)),
      error: (error: unknown) => this.messages.error(errorText(error)),
    });
  }
}
