import { HashLocationStrategy } from '@angular/common';
import { Injectable } from '@angular/core';

/**
 * Hash routing with GWT-style history tokens: the URL is `/ng/#manufacturer`
 * (like the GWT app's `#manufacturer`), not Angular's default `/ng/#/manufacturer`.
 * Both forms are accepted when reading the URL.
 */
@Injectable()
export class GwtHashLocationStrategy extends HashLocationStrategy {
  override path(includeHash = false): string {
    const path = super.path(includeHash);
    return path.length === 0 || path.startsWith('/') ? path : '/' + path;
  }

  override prepareExternalUrl(internal: string): string {
    const token = internal.startsWith('/') ? internal.substring(1) : internal;
    return token.length > 0 ? '#' + token : '';
  }
}
