import { DestroyRef, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { NavigationSkipped, NavigationStart, Router } from '@angular/router';
import { filter } from 'rxjs';

/**
 * Calls `callback` whenever a navigation starts (a menubar link, Back/Forward, a typed URL),
 * even to the current screen. Used to auto-hide popups on navigation.
 * Must be called in an injection context; stops when the caller is destroyed.
 */
export function onNavigationStart(callback: () => void): void {
  inject(Router)
    .events.pipe(
      // NavigationSkipped: a menubar link to the screen already shown.
      filter((event) => event instanceof NavigationStart || event instanceof NavigationSkipped),
      takeUntilDestroyed(inject(DestroyRef)),
    )
    .subscribe(() => callback());
}
